CARDIO.register({"item":"p188","meta":{"num":"p188","label":"188","spe":"pneumo","short":"Asthme, rhinite","title":"Asthme, rhinite","section":"P","chapter":6,"pages":"84-102","sdd":[]},"objectives":[{"id":"p188-obj-01","rank":"A","rubric":"Définition","title":"Connaître la définition de l'asthme et de la rhinite allergique (chez l'adulte et l'enfant, selon l'âge chez l'enfant)","desc":""},{"id":"p188-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d'une rhinite allergique chez l'enfant et l'adulte","desc":""},{"id":"p188-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic positif et du diagnostic différentiel d'un asthme chez l'enfant et l'adulte","desc":""},{"id":"p188-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Identifier le caractère professionnel d'une allergie respiratoire : démarche diagnostique étiologique","desc":""},{"id":"p188-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités d'évaluation du contrôle de l'asthme","desc":""},{"id":"p188-obj-06","rank":"B","rubric":"Physiopathologie","title":"Connaître la physiopathologie et immunopathologie de l'asthme et de la rhinite allergique","desc":""},{"id":"p188-obj-07","rank":"B","rubric":"Étiologies","title":"Connaître les principaux métiers à risque d'asthme professionnel","desc":""},{"id":"p188-obj-08","rank":"A","rubric":"Étiologies","title":"Connaître les grandes étiologies professionnelles","desc":""},{"id":"p188-obj-09","rank":"B","rubric":"Étiologies","title":"Connaître les principaux facteurs de non contrôle de l'asthme et savoir rechercher les facteurs précipitants d'un asthme aigu grave","desc":""},{"id":"p188-obj-10","rank":"A","rubric":"Ex. complémentaires","title":"Connaître la sémiologie RP d'un pneumomédiastin","desc":""},{"id":"p188-obj-11","rank":"B","rubric":"Ex. complémentaires","title":"Connaître les grandes caractéristiques du syndrome obstructif en EFR et savoir interpréter un DEP","desc":""},{"id":"p188-obj-12","rank":"B","rubric":"Ex. complémentaires","title":"Connaître les indications des tests immuno-allergiques","desc":""},{"id":"p188-obj-13","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités d'évaluation du contrôle de l'asthme","desc":""},{"id":"p188-obj-14","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'exacerbation d'asthme chez l'enfant et l'adulte","desc":""},{"id":"p188-obj-15","rank":"A","rubric":"Identifier une urgence","title":"Connaître les signes de gravité d'une exacerbation d'asthme chez l'enfant et l'adulte","desc":""},{"id":"p188-obj-16","rank":"B","rubric":"Prévalence, épidémiologie","title":"Connaître la fréquence et les facteurs de risque de l'asthme et de la rhinite allergique dans la population adulte et pédiatrique","desc":""},{"id":"p188-obj-17","rank":"A","rubric":"Prise en charge","title":"Connaître les principes thérapeutiques de la rhinite allergique","desc":""},{"id":"p188-obj-18","rank":"A","rubric":"Prise en charge","title":"Connaître les grands principes thérapeutiques de fond de la maladie asthmatique avec les principales classes thérapeutiques utilisables","desc":""},{"id":"p188-obj-19","rank":"A","rubric":"Contenu multimédia","title":"Connaître la sémiologie RP d'une distension thoracique","desc":""},{"id":"p188-obj-20","rank":"A","rubric":"Contenu multimédia","title":"Exemple RP asthme avec pneumomédiastin et emphysème sous cutané","desc":""},{"id":"p188-obj-21","rank":"A","rubric":"Prise en charge","title":"Connaître les objectifs et les modalités de surveillance du traitement de fond de l'asthme","desc":""},{"id":"p188-obj-22","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités d'initiation du traitement d'urgence d'une crise d'asthme chez l'enfant et l'adulte","desc":""},{"id":"p188-obj-23","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de l'éducation thérapeutique de l'asthme et les plans d'action pour améliorer l'observance dans l'asthme","desc":""},{"id":"p188-obj-24","rank":"A","rubric":"Prise en charge","title":"Connaître les principales mesures d'éviction allergénique dans l'asthme et la rhinite allergique, y compris professionnels","desc":""},{"id":"p188-obj-25","rank":"A","rubric":"Prise en charge","title":"Connaître la place des antihistaminiques et des corticoïdes dans la rhinite allergique","desc":""},{"id":"p188-obj-26","rank":"B","rubric":"Suivi et/ou pronostic","title":"Connaître les complications de l'asthme","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p188-qroc-001","type":"QROC","rank":"A","objective":"p188-obj-01","tags":["définition"],"difficulty":1,"question":"Dans la définition de l'asthme, quelle anomalie fonctionnelle, variable dans le temps et réversible, doit s'associer aux symptômes respiratoires ?","answer":"Une obstruction des voies aériennes (TVO réversible)","accept":["obstruction bronchique","obstruction des voies aériennes","trouble ventilatoire obstructif","TVO"],"keywords":["obstruct"],"explanation":"L'asthme associe des symptômes respiratoires variables (dyspnée, sifflements, oppression thoracique, toux) ET une obstruction des voies aériennes variable dans le temps et/ou réversible sous bronchodilatateur. Le diagnostic exige les deux éléments.","src":"p. 86-87"},{"id":"p188-qroc-002","type":"QROC","rank":"A","objective":"p188-obj-14","tags":["définition","clinique"],"difficulty":1,"question":"Pendant combien de jours minimum les symptômes s'aggravent-ils progressivement dans une exacerbation d'asthme ?","answer":"Au moins 2 jours","accept":["2 jours","deux jours","au moins 2 jours","au moins deux jours"],"keywords":["2"],"explanation":"Exacerbation = aggravation progressive des symptômes pendant au moins 2 jours, qui impose de modifier le traitement (souvent avec recours inopiné aux soins), non calmée par les BDCA répétés et sans retour à l'état habituel. À distinguer des symptômes brefs, qui cèdent en général en moins de 20 minutes.","src":"p. 86"},{"id":"p188-qroc-003","type":"QROC","rank":"A","objective":"p188-obj-03","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Chez l'adulte, le trouble ventilatoire obstructif (TVO) est défini par un rapport VEMS/CVF inférieur à quelle valeur ?","answer":"0,7","accept":["0,7","0.7","70 %"],"keywords":["0,7"],"explanation":"Chez l'adulte, TVO = VEMS/CVF < 0,7. On recherche ensuite sa réversibilité après un bronchodilatateur de courte durée d'action.","src":"p. 87"},{"id":"p188-qroc-004","type":"QROC","rank":"A","objective":"p188-obj-03","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quelle augmentation du VEMS après bronchodilatateur de courte durée d'action définit la réversibilité (valeur absolue en mL ET relative en %) ?","answer":"Plus de 200 mL ET plus de 12 % de la valeur initiale","accept":["200 ml et 12","12 % et 200 ml","plus de 200 ml et plus de 12 %","> 200 ml et > 12 %"],"keywords":["200","12"],"explanation":"Réversibilité = gain de VEMS > 200 mL ET > 12 % par rapport à la valeur avant bronchodilatateur. Elle est évocatrice mais non pathognomonique : c'est l'association à des symptômes évocateurs qui permet le diagnostic.","src":"p. 88"},{"id":"p188-qroc-005","type":"QROC","rank":"A","objective":"p188-obj-03","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quel test de provocation bronchique pharmacologique recherche une hyperréactivité bronchique lorsque la spirométrie est normale ?","answer":"Le test à la méthacholine","accept":["méthacholine","test à la méthacholine","test de provocation à la méthacholine"],"keywords":["méthacholine"],"explanation":"Si la spirométrie est normale, une HRB peut être documentée par un test à la méthacholine (ou un test d'effort). Une spirométrie normale en consultation n'élimine pas l'asthme : on renouvelle l'examen avec un test de réversibilité ou de provocation.","src":"p. 87, 89"},{"id":"p188-qroc-006","type":"QROC","rank":"A","objective":"p188-obj-03","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen d'imagerie est indispensable lors de la première consultation d'un asthmatique, notamment pour éliminer un obstacle bronchique ou trachéal ?","answer":"La radiographie thoracique","accept":["radiographie de thorax","radiographie du thorax","radio thorax","radio du thorax","radiographie pulmonaire"],"keywords":["radio"],"explanation":"La radiographie thoracique est indispensable à la 1re consultation (diagnostic différentiel). Elle n'est pas recommandée dans le suivi, mais reste indiquée lors d'une exacerbation grave (pneumothorax, pneumonie).","src":"p. 89"},{"id":"p188-qroc-007","type":"QROC","rank":"A","objective":"p188-obj-03","tags":["imagerie","pièges"],"difficulty":2,"question":"Dans l'asthme, dans quelle situation peut-on envisager une tomodensitométrie thoracique ?","answer":"Asthme dont le contrôle est difficile","accept":["asthme difficile à contrôler","asthme mal contrôlé","asthme non contrôlé","contrôle difficile"],"keywords":["contrôle"],"explanation":"La TDM n'est pas nécessaire en routine. Elle est réservée aux asthmes difficiles à contrôler, pour chercher une pathologie associée (aspergillose bronchopulmonaire allergique, pneumonie éosinophile, granulomatose éosinophile avec polyangéite).","src":"p. 89"},{"id":"p188-qroc-008","type":"QROC","rank":"A","objective":"p188-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Quels sont les deux diagnostics différentiels cliniques de l'asthme qui ne comportent ni TVO ni hyperréactivité bronchique ?","answer":"Dysfonction des cordes vocales et syndrome d'hyperventilation","accept":["dysfonction des cordes vocales et syndrome d'hyperventilation","syndrome d'hyperventilation et dysfonction des cordes vocales"],"keywords":["cordes vocales","hyperventilation"],"explanation":"Ces deux diagnostics sont cliniques, sans obstruction ni HRB. Les autres diagnostics différentiels (BPCO, bronchectasies, mucoviscidose, bronchiolites constrictives, corps étranger, tumeurs trachéo-bronchiques, insuffisance cardiaque) s'accompagnent d'un TVO non complètement réversible.","src":"p. 89"},{"id":"p188-qroc-009","type":"QROC","rank":"A","objective":"p188-obj-08","tags":["étiologie"],"difficulty":1,"question":"Quel agent, composant des peintures polyuréthanes, est en cause dans l'asthme professionnel des peintres au pistolet de l'industrie automobile ?","answer":"Les isocyanates","accept":["isocyanate","isocyanates"],"keywords":["isocyanat"],"explanation":"Peintres au pistolet → isocyanates ; les solvants de peinture ne font qu'aggraver cet asthme par leur effet irritant. On retrouve aussi des isocyanates dans les vernis des travailleurs du bois.","src":"p. 90"},{"id":"p188-qroc-010","type":"QROC","rank":"A","objective":"p188-obj-08","tags":["étiologie"],"difficulty":1,"question":"Quel produit de décoloration capillaire est un agent majeur d'asthme professionnel chez les coiffeurs ?","answer":"Les persulfates alcalins","accept":["persulfate","persulfates","persulfate alcalin","persulfates alcalins"],"keywords":["persulfat"],"explanation":"Coiffeurs → persulfates alcalins (décolorants), mais aussi teintures capillaires et produits de permanente.","src":"p. 90"},{"id":"p188-qroc-011","type":"QROC","rank":"A","objective":"p188-obj-08","tags":["étiologie"],"difficulty":1,"question":"Chez le boulanger-pâtissier, de quelles farines provient l'asthme professionnel ?","answer":"Farines de céréales (blé, seigle)","accept":["farines de céréales","farine de blé","farines de blé","farine de seigle","blé et seigle","farine"],"keywords":["farine"],"explanation":"Boulanger-pâtissier → farines de céréales (blé, seigle). Sont aussi incriminés les enzymes améliorants de la farine (alpha-amylase, cellulase) et les contaminants (acariens de stockage, blatte).","src":"p. 90"},{"id":"p188-qroc-012","type":"QROC","rank":"B","objective":"p188-obj-04","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Quelle mesure répétée, sur et hors du lieu de travail, objective la relation entre les symptômes et le travail dans un asthme professionnel ?","answer":"Le débit expiratoire de pointe (journal de DEP)","accept":["DEP","débit expiratoire de pointe","débit de pointe","journal de DEP","peak flow"],"keywords":["pointe"],"explanation":"Le journal de DEP, avec sa variabilité sur et hors du lieu de travail, objective le lien symptômes-travail (le VEMS peut aussi être suivi). Autres arguments : asthme de novo au poste de travail, métier à risque, amélioration le week-end et en congés, sensibilisation IgE-dépendante.","src":"p. 88, 90"},{"id":"p188-qroc-013","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["traitement"],"difficulty":1,"question":"Quelle classe médicamenteuse constitue la base du traitement de fond de l'asthme ?","answer":"Les corticoïdes inhalés (CSI)","accept":["CSI","corticoïdes inhalés","corticoïde inhalé","corticostéroïdes inhalés","corticostéroïde inhalé","corticothérapie inhalée"],"keywords":["inhal"],"explanation":"Le traitement de fond repose sur la corticothérapie inhalée (seule ou associée à un bronchodilatateur), à prendre tous les jours dès que le diagnostic est évoqué. C'est le traitement anti-inflammatoire le plus efficace de l'asthme.","src":"p. 91, 100"},{"id":"p188-qroc-014","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["traitement"],"difficulty":1,"question":"Quelle classe médicamenteuse constitue le traitement de secours de base des symptômes d'asthme ?","answer":"Les β2-mimétiques inhalés de courte durée d'action (BDCA)","accept":["BDCA","β2-mimétique de courte durée d'action","bronchodilatateur de courte durée d'action","salbutamol","terbutaline"],"keywords":["courte"],"explanation":"Traitement de secours = BDCA inhalé (salbutamol ou terbutaline). En alternative, l'association CSI/formotérol dans le même dispositif est proposée : le formotérol est le seul BDLA à action rapide.","src":"p. 92"},{"id":"p188-qroc-015","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["traitement","pièges"],"difficulty":2,"question":"Quel traitement de l'asthme ne doit jamais être prescrit seul, car il expose à un risque accru de décès ?","answer":"Un β2-mimétique de longue durée d'action (BDLA) seul","accept":["BDLA","BDLA seul","β2-mimétique de longue durée d'action","bronchodilatateur de longue durée d'action","longue durée d'action"],"keywords":["longue"],"explanation":"L'asthme est une maladie inflammatoire : le traitement repose sur les CSI. Un BDLA doit toujours être associé à un CSI (idéalement dans le même dispositif), car son utilisation seule augmente le risque de décès par asthme.","src":"p. 91, 100"},{"id":"p188-qroc-016","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["traitement"],"difficulty":2,"question":"À partir de quelle fréquence de symptômes met-on en route, en pratique, le traitement de fond de l'asthme ?","answer":"Plus de 2 fois par mois","accept":["plus de 2 fois par mois","plus de deux fois par mois","> 2 fois par mois","plus de 2 fois/mois"],"keywords":["2","mois"],"explanation":"Des symptômes survenant plus de 2 fois par mois justifient la mise en route d'un traitement de fond quotidien. Il débute par un palier 2 ou 3 selon le niveau de contrôle.","src":"p. 91"},{"id":"p188-qroc-017","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["traitement"],"difficulty":2,"question":"Quel traitement de fond correspond au palier 3 chez l'adulte ?","answer":"CSI faible dose + BDLA","accept":["CSI faible dose + BDLA","CSI faible dose et BDLA","CSI faible dose avec BDLA","CSI à faible dose associé à un BDLA","BDLA + CSI faible dose"],"keywords":["faible","bdla"],"explanation":"Palier 3 = CSI faible dose + BDLA. Palier 2 = CSI faible dose seul ; palier 4 = CSI dose modérée + BDLA ; palier 5 = CSI dose forte + BDLA avec avis pneumologique, ajout de tiotropium et discussion d'une biothérapie.","src":"p. 91"},{"id":"p188-qroc-018","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["définition","traitement"],"difficulty":2,"question":"Quel palier de traitement de fond définit un asthme sévère ?","answer":"Le palier 5","accept":["palier 5","le palier 5","5"],"keywords":["5"],"explanation":"La sévérité de l'asthme s'évalue rétrospectivement selon la pression thérapeutique nécessaire au contrôle : un asthme sévère est un asthme qui nécessite un traitement de palier 5 (CSI dose forte + BDLA, avis pneumologique, tiotropium, biothérapie à discuter).","src":"p. 91-92, 95"},{"id":"p188-qroc-019","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["pièges","traitement"],"difficulty":1,"question":"Quelle classe médicamenteuse, y compris sous forme de collyre, peut aggraver un asthme ?","answer":"Les β-bloquants","accept":["bêtabloquants","bêta-bloquants","beta bloquants","β-bloquants","bétabloquants"],"keywords":["bloquant"],"explanation":"Les β-bloquants (même en collyre) peuvent aggraver l'asthme : chez un asthmatique non contrôlé, leur prescription nécessite l'avis du pneumologue.","src":"p. 93"},{"id":"p188-qroc-020","type":"QROC","rank":"A","objective":"p188-obj-18","tags":["pièges","traitement"],"difficulty":2,"question":"Quelles molécules sont contre-indiquées chez un asthmatique ayant un antécédent d'hypersensibilité à celles-ci ?","answer":"L'aspirine et les AINS","accept":["aspirine et AINS","aspirine","AINS","anti-inflammatoires non stéroïdiens"],"keywords":["aspirine"],"explanation":"Contre-indication à l'aspirine et aux AINS en cas d'hypersensibilité connue. L'association asthme + polypose naso-sinusienne + intolérance à ces molécules est le syndrome de Widal, facteur de risque de décès par asthme.","src":"p. 93, 97"},{"id":"p188-qroc-021","type":"QROC","rank":"A","objective":"p188-obj-23","tags":["prévention","traitement"],"difficulty":1,"question":"Quel document écrit, remis et expliqué au patient asthmatique, précise sa conduite à tenir en cas d'exacerbation ?","answer":"Le plan d'action écrit","accept":["plan d'action","plan d'action écrit","plan d'action personnalisé"],"keywords":["plan"],"explanation":"Le plan d'action comprend l'identification de la gravité par le patient (symptômes et DEP), le traitement à utiliser et les modalités d'accès aux soins en cas de signes de gravité ou d'échec. Sa compréhension est vérifiée à chaque suivi.","src":"p. 93, 95"},{"id":"p188-qroc-022","type":"QROC","rank":"A","objective":"p188-obj-13","tags":["suivi"],"difficulty":1,"question":"À partir de quel score ACT (sur 25) l'asthme est-il considéré comme bien contrôlé ?","answer":"Au moins 20/25","accept":["20","20/25","au moins 20","supérieur ou égal à 20"],"keywords":["20"],"explanation":"L'ACT comporte 5 questions cotées de 1 à 5 sur les 4 dernières semaines : asthme bien contrôlé si ≥ 20/25, insuffisamment contrôlé si < 20/25.","src":"p. 93-94"},{"id":"p188-qroc-023","type":"QROC","rank":"A","objective":"p188-obj-05","tags":["suivi"],"difficulty":2,"question":"Un asthme est contrôlé si le nombre de cures de corticothérapie systémique sur l'année précédente est inférieur à quelle valeur ?","answer":"2 cures","accept":["2","2 cures","moins de 2","deux cures"],"keywords":["2"],"explanation":"Critères de contrôle : symptômes contrôlés (ACT), exacerbations rares (< 2 cures de corticoïdes systémiques l'année précédente) et absence d'obstruction (VEMS/CVF > 0,7 et VEMS ≥ 80 %). Chaque cure doit faire réévaluer le traitement de fond.","src":"p. 93"},{"id":"p188-qroc-024","type":"QROC","rank":"A","objective":"p188-obj-21","tags":["traitement","suivi"],"difficulty":2,"question":"Quand l'asthme est contrôlé, quel traitement de fond minimal faut-il maintenir chez l'adulte et l'adolescent ?","answer":"Au minimum un CSI à faible dose","accept":["CSI faible dose","CSI à faible dose","corticoïde inhalé à faible dose","corticoïdes inhalés à faible dose","faible dose de CSI"],"keywords":["faible"],"explanation":"Quand l'asthme est contrôlé, on poursuit le même traitement ou on le diminue, en cherchant la dose minimale efficace, sans descendre sous un CSI faible dose chez l'adulte et l'adolescent.","src":"p. 94"},{"id":"p188-qroc-025","type":"QROC","rank":"A","objective":"p188-obj-21","tags":["traitement","suivi"],"difficulty":2,"question":"Avant d'augmenter le traitement de fond d'un asthme non contrôlé, quelles causes de non-contrôle faut-il d'abord vérifier ?","answer":"Observance, technique d'inhalation, facteurs favorisants","accept":["observance, technique d'inhalation et facteurs favorisants","observance, technique de prise et facteurs favorisants"],"keywords":["observance","technique","favorisant"],"explanation":"Avant de monter d'un palier, on vérifie l'observance, la technique de prise des dispositifs d'inhalation et les facteurs favorisants. Si le non-contrôle persiste, on a recours au spécialiste ou à un centre expert de l'asthme sévère.","src":"p. 94"},{"id":"p188-qroc-026","type":"QROC","rank":"A","objective":"p188-obj-15","tags":["urgence","clinique"],"difficulty":1,"question":"Comment appelle-t-on l'association asthme, polypose naso-sinusienne et intolérance à l'aspirine et aux AINS, facteur de risque de décès par asthme ?","answer":"Le syndrome de Widal","accept":["Widal","syndrome de Widal","maladie de Widal"],"keywords":["widal"],"explanation":"Syndrome de Widal = asthme + polypose naso-sinusienne + intolérance à l'aspirine et aux AINS. L'hypersensibilité à ces molécules figure parmi les facteurs de risque de décès par asthme.","src":"p. 97"},{"id":"p188-qroc-027","type":"QROC","rank":"A","objective":"p188-obj-15","tags":["urgence","clinique"],"difficulty":1,"question":"Quel signe à l'auscultation figure parmi les signes de défaillance d'une exacerbation d'asthme ?","answer":"Le silence auscultatoire","accept":["silence auscultatoire","silence respiratoire","thorax silencieux"],"keywords":["silence"],"explanation":"Les signes de défaillance comprennent le silence auscultatoire, la respiration paradoxale, les troubles de la conscience, la bradycardie et le collapsus. Une ventilation mécanique est prévue en cas de signe de gravité extrême.","src":"p. 96, 98"},{"id":"p188-qroc-028","type":"QROC","rank":"A","objective":"p188-obj-15","tags":["urgence","clinique"],"difficulty":2,"question":"Quelle fréquence respiratoire (par minute) est un critère de gravité d'une exacerbation d'asthme ?","answer":"Plus de 30/min","accept":["30","plus de 30","FR > 30","supérieure à 30"],"keywords":["30"],"explanation":"Parmi les critères de gravité : parole par mots, position penchée en avant, agitation, FR > 30/min, muscles respiratoires accessoires, FC > 120/min, SpO2 < 90 % en air, DEP ≤ 50 %.","src":"p. 96"},{"id":"p188-qroc-029","type":"QROC","rank":"A","objective":"p188-obj-15","tags":["urgence","clinique"],"difficulty":2,"question":"Quel seuil de DEP, exprimé en % de la meilleure valeur (ou de la valeur théorique), est un critère de gravité d'une exacerbation ?","answer":"DEP ≤ 50 %","accept":["50","50 %","≤ 50 %","inférieur ou égal à 50 %"],"keywords":["50"],"explanation":"Un DEP ≤ 50 % de la meilleure valeur (ou de la valeur théorique si elle est inconnue), ou impossible à réaliser, est un critère de gravité. Le DEP se répète pour surveiller l'évolution sous traitement.","src":"p. 96, 98"},{"id":"p188-qroc-030","type":"QROC","rank":"A","objective":"p188-obj-10","tags":["imagerie","complications"],"difficulty":2,"question":"Citez les trois complications que l'on recherche sur la radiographie thoracique lors d'une exacerbation d'asthme.","answer":"Pneumothorax, pneumomédiastin, emphysème sous-cutané","accept":["pneumothorax, pneumomédiastin et emphysème sous-cutané","pneumothorax, emphysème sous-cutané et pneumomédiastin"],"keywords":["pneumothorax","pneumomédiastin","emphysème"],"explanation":"La radiographie thoracique, réalisée en parallèle du traitement, cherche un diagnostic différentiel ou une complication : pneumothorax, pneumomédiastin, emphysème sous-cutané. Elle ne doit pas retarder la prise en charge.","src":"p. 97"},{"id":"p188-qroc-031","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["urgence","biologie"],"difficulty":2,"question":"Que recherche la gazométrie artérielle réalisée en cas de critères de sévérité d'une exacerbation d'asthme ?","answer":"Une hypercapnie","accept":["hypercapnie","une hypercapnie","PaCO2 élevée"],"keywords":["hypercapn"],"explanation":"La gazométrie artérielle est demandée en parallèle du traitement, en présence de critères de sévérité, à la recherche d'une hypercapnie. De fortes doses de BDCA peuvent donner une acidose lactique, sans traitement spécifique.","src":"p. 97"},{"id":"p188-qroc-032","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["traitement","urgence"],"difficulty":2,"question":"Quelle dose de salbutamol nébulisé est administrée par séance, répétée toutes les 20 minutes pendant la première heure, dans une exacerbation en milieu médicalisé ?","answer":"5 mg (sur 10 à 15 minutes)","accept":["5 mg","5mg","5 milligrammes"],"keywords":["5"],"explanation":"En milieu médicalisé : nébulisation de 5 mg (salbutamol ou terbutaline) sur 10 à 15 min, répétée toutes les 20 min pendant la 1re heure, avec l'oxygène comme gaz vecteur.","src":"p. 97-98"},{"id":"p188-qroc-033","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["traitement","urgence"],"difficulty":2,"question":"Quelle posologie de prednisone ou de prednisolone prescrit-on chez l'adulte dans une exacerbation d'asthme ?","answer":"0,5 à 1 mg/kg/j, sans dépasser 60 mg/j","accept":["0,5 à 1 mg/kg","0,5-1 mg/kg","0,5 à 1 mg/kg/j max 60 mg"],"keywords":["0,5","60"],"explanation":"Corticothérapie systémique orale, à débuter sans retard : 0,5 à 1 mg/kg/j sans dépasser 60 mg/j, pendant 5 à 7 jours puis arrêt sans décroissance.","src":"p. 97"},{"id":"p188-qroc-034","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["traitement","urgence"],"difficulty":1,"question":"Pendant combien de jours prescrit-on la corticothérapie orale d'une exacerbation d'asthme, avant arrêt sans décroissance ?","answer":"5 à 7 jours","accept":["5 à 7 jours","5-7 jours","5 à 7 j","entre 5 et 7 jours"],"keywords":["5","7"],"explanation":"Durée de 5 à 7 jours, puis arrêt sans décroissance. La voie orale est toujours préférée aux voies IM et IV en l'absence de trouble de la conscience ; l'efficacité apparaît en 4 à 6 h, d'où l'intérêt de débuter sans retard.","src":"p. 97, 100"},{"id":"p188-qroc-035","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["traitement","urgence"],"difficulty":2,"question":"Quel objectif de saturation en oxygène vise-t-on dans la prise en charge d'une exacerbation sévère d'asthme ?","answer":"SpO2 de 93 à 95 %","accept":["93 à 95","93-95","93 à 95 %"],"keywords":["93","95"],"explanation":"Exacerbation sévère : oxygène pour une SpO2 de 93 à 95 %, dans une prise en charge en soins intensifs. Dans l'exacerbation modérée, l'oxygène n'est donné qu'en cas d'hypoxémie, avec un objectif de 94 à 98 %.","src":"p. 97-98"},{"id":"p188-qroc-036","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["traitement","urgence"],"difficulty":1,"question":"Quel anticholinergique nébulisé associe-t-on aux β2-mimétiques dans l'asthme aigu grave ?","answer":"L'ipratropium","accept":["ipratropium","l'ipratropium","ipratropium nébulisé"],"keywords":["ipratropium"],"explanation":"Asthme aigu grave : β2-mimétiques nébulisés à forte dose + ipratropium (0,5 mg sur 10 à 15 min, répétable toutes les 8 h). Le gaz vecteur de la nébulisation est l'oxygène.","src":"p. 98, 100"},{"id":"p188-qroc-037","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["pièges","traitement"],"difficulty":2,"question":"Quelle est la contre-indication de la corticothérapie systémique dans une exacerbation sévère d'asthme ?","answer":"Aucune","accept":["aucune","aucune contre-indication","pas de contre-indication","pas de contre indication"],"keywords":["aucune"],"explanation":"La corticothérapie d'une exacerbation sévère ne doit pas être retardée et n'a aucune contre-indication, même en cas de suspicion d'infection associée (y compris COVID-19).","src":"p. 98"},{"id":"p188-qroc-038","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["urgence","traitement"],"difficulty":2,"question":"Quel monitorage est obligatoire quand on utilise un β2-mimétique injectable à la seringue électrique dans l'asthme aigu grave ?","answer":"Le scope","accept":["scope","scope cardiaque","monitorage cardiaque","monitoring cardiaque"],"keywords":["scope"],"explanation":"Les β2-mimétiques injectables (salbutamol à dose progressivement croissante, dès 0,25-0,5 mg/h) ne s'utilisent qu'en cas d'échec, sous scope : effet adrénergique et hypokaliémie majorée par la corticothérapie.","src":"p. 98"},{"id":"p188-qroc-039","type":"QROC","rank":"A","objective":"p188-obj-22","tags":["suivi","urgence"],"difficulty":1,"question":"Au bout de quel délai réévalue-t-on le patient (DEP, symptômes) après le début du traitement d'une exacerbation, pour décider du retour à domicile ou de l'hospitalisation ?","answer":"1 heure","accept":["1 h","1h","1 heure","une heure","60 minutes"],"keywords":["heure"],"explanation":"À 1 h : DEP normalisé et symptômes disparus → retour à domicile avec traitement et rendez-vous ; sinon, on discute l'hospitalisation. En cas d'aggravation ou de non-amélioration après 1 h, transfert en soins intensifs (transport médicalisé).","src":"p. 98-99"},{"id":"p188-qroc-040","type":"QROC","rank":"A","objective":"p188-obj-02","tags":["définition","diagnostic"],"difficulty":1,"question":"Que signifie l'acronyme PAREO, qui regroupe les symptômes de la rhinite chronique ?","answer":"Prurit, Anosmie, Rhinorrhée, Éternuements, Obstruction nasale","accept":["prurit, anosmie, rhinorrhée, éternuements, obstruction nasale","prurit, anosmie, rhinorrhée, éternuements, obstruction"],"keywords":["prurit","anosmie","obstruction"],"explanation":"PAREO = Prurit, Anosmie, Rhinorrhée, Éternuements, Obstruction nasale (acronyme proche : APERO). Le diagnostic de rhinite allergique est clinique et repose aussi sur l'examen des fosses nasales et la recherche de sensibilisations.","src":"p. 85, 101"},{"id":"p188-qroc-041","type":"QROC","rank":"A","objective":"p188-obj-01","tags":["définition","physiopathologie"],"difficulty":2,"question":"Quel type d'inflammation, rattachée à une exposition aux pneumallergènes, caractérise la rhinite allergique ?","answer":"Une inflammation IgE-dépendante","accept":["IgE-dépendante","IgE dépendante","inflammation médiée par les IgE","immunoglobulines E"],"keywords":["ige"],"explanation":"La rhinite allergique est l'expression clinique d'une rhinite avec stigmates d'allergie respiratoire : inflammation IgE-dépendante rattachable à l'exposition aux pneumallergènes. Le patient est souvent polysensibilisé : l'interrogatoire établit les allergènes réellement responsables.","src":"p. 85"},{"id":"p188-qroc-042","type":"QROC","rank":"A","objective":"p188-obj-02","tags":["diagnostic"],"difficulty":1,"question":"Quelle durée annuelle de symptômes sépare la rhinite allergique intermittente de la rhinite allergique persistante ?","answer":"4 semaines consécutives par an","accept":["4 semaines","quatre semaines","4 semaines par an","4 semaines consécutives"],"keywords":["4","semaines"],"explanation":"Intermittente : ≤ 4 semaines consécutives par an ; persistante : > 4 semaines consécutives par an. La sévérité (légère ou sévère) dépend du retentissement sur le sommeil et les activités.","src":"p. 101"},{"id":"p188-qroc-043","type":"QROC","rank":"A","objective":"p188-obj-25","tags":["traitement"],"difficulty":1,"question":"Quelles sont les deux classes de médicaments utilisées pour traiter la rhinite allergique ?","answer":"Antihistaminiques H1 (2e génération) et corticoïdes nasaux","accept":["antihistaminiques et corticoïdes nasaux","antihistaminiques et corticoïdes locaux","antihistaminiques H1 et corticoïdes locaux"],"keywords":["antihistaminique","cortico"],"explanation":"Antihistaminiques H1 de 2e génération (voie orale et/ou locale) et corticoïdes nasaux, sans préférence en 1re intention ; on peut les associer en cas d'inefficacité. Le lavage nasal au sérum physiologique complète la prise en charge.","src":"p. 85, 101"},{"id":"p188-qroc-044","type":"QROC","rank":"A","objective":"p188-obj-17","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle classe de traitement nasal est déconseillée au long cours dans la rhinite allergique ?","answer":"Les vasoconstricteurs nasaux","accept":["vasoconstricteurs nasaux","vasoconstricteur nasal","vasoconstricteurs"],"keywords":["vasoconstricteur"],"explanation":"Les vasoconstricteurs nasaux sont déconseillés au long cours : risque de rhinite iatrogène et, chez les coronariens, risque de coronarospasme.","src":"p. 102"},{"id":"p188-qroc-045","type":"QROC","rank":"A","objective":"p188-obj-24","tags":["traitement","prévention"],"difficulty":2,"question":"Quelles interventions peuvent modifier l'histoire naturelle de la rhinite allergique ?","answer":"Éviction allergénique et immunothérapie allergénique","accept":["mesures d'éviction et immunothérapie allergénique","éviction et immunothérapie"],"keywords":["éviction","immunothérapie"],"explanation":"Les antihistaminiques et les corticoïdes locaux traitent les symptômes ; ce sont les mesures d'éviction et l'immunothérapie allergénique qui peuvent changer l'histoire naturelle de la maladie.","src":"p. 85"},{"id":"p188-qcm-101","type":"QRM","rank":"A","objective":"p188-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Une jeune femme de 24 ans consulte pour des épisodes répétés de gêne respiratoire avec sifflements et toux. Quels éléments cliniques sont en faveur d'un asthme ?","options":[{"t":"Plusieurs symptômes respiratoires associés, variables dans le temps et réversibles","ok":true,"why":"C'est le fil conducteur de l'histoire clinique : symptômes associés, variables et réversibles."},{"t":"Symptômes strictement identiques d'un jour à l'autre, sans aucune variation","ok":false,"why":"À l'inverse, la variabilité dans le temps et en intensité est la règle."},{"t":"Aggravation des symptômes la nuit ou au petit matin","ok":true,"why":"Une recrudescence nocturne ou matinale fait partie des arguments cliniques."},{"t":"Sibilants obligatoirement entendus à l'auscultation le jour de la consultation","ok":false,"why":"Les sibilants peuvent être présents le jour de l'examen ou seulement dans le passé : leur absence ce jour-là n'élimine pas l'asthme."},{"t":"Symptômes déclenchés par l'exercice, les allergènes, le rire ou des irritants comme le tabac","ok":true,"why":"Infections virales, exercice, allergènes, irritants, émotions et rire sont des déclencheurs typiques."}],"explanation":"On suspecte l'asthme sur l'histoire (symptômes multiples, variables, réversibles, déclencheurs typiques, aggravation nocturne ou matinale), puis on le confirme par les données fonctionnelles respiratoires.","trap":"Des sibilants présents « au présent ou dans le passé » suffisent : leur absence le jour de l'examen n'élimine pas le diagnostic.","src":"p. 87, 89"},{"id":"p188-qcm-102","type":"QRM","rank":"A","objective":"p188-obj-03","tags":["paraclinique","diagnostic"],"difficulty":3,"stem":"Chez un patient de 45 ans, la spirométrie retrouve un rapport VEMS/CVF à 0,63. Le VEMS passe de 2,1 L à 2,6 L après inhalation d'un bronchodilatateur de courte durée d'action. Quelles propositions sont exactes ?","options":[{"t":"La spirométrie est normale","ok":false,"why":"Un VEMS/CVF inférieur à 0,7 définit un trouble ventilatoire obstructif chez l'adulte."},{"t":"Il existe un trouble ventilatoire obstructif","ok":true,"why":"VEMS/CVF = 0,63, donc inférieur à 0,7."},{"t":"Le gain relatif de VEMS est inférieur à 12 %","ok":false,"why":"(2,6 − 2,1) / 2,1 = 0,24, soit 24 % : supérieur à 12 %."},{"t":"La réversibilité du VEMS est significative","ok":true,"why":"Le gain est de 500 mL (plus de 200 mL) et de 24 % (plus de 12 %) par rapport à la valeur initiale."},{"t":"Cette réversibilité est pathognomonique de l'asthme","ok":false,"why":"Elle est évocatrice mais non pathognomonique : c'est l'association à des symptômes évocateurs qui conduit au diagnostic."}],"explanation":"TVO si VEMS/CVF < 0,7 ; réversibilité si le VEMS augmente de plus de 200 mL ET de plus de 12 % après bronchodilatateur de courte durée d'action. Le diagnostic associe ces données aux symptômes.","src":"p. 87-88"},{"id":"p188-qcm-103","type":"QRM","rank":"A","objective":"p188-obj-03","tags":["paraclinique","diagnostic"],"difficulty":1,"stem":"Un homme de 30 ans est vu pour la première fois pour une suspicion d'asthme. Quels éléments comprend le bilan initial en consultation programmée ?","options":[{"t":"Une tomodensitométrie thoracique systématique","ok":false,"why":"Elle n'est pas nécessaire : elle est réservée aux asthmes difficiles à contrôler."},{"t":"Une radiographie thoracique pour écarter un diagnostic différentiel","ok":true,"why":"Elle est indispensable à la 1re consultation (obstacle bronchique ou trachéal notamment)."},{"t":"Une spirométrie avec test de réversibilité","ok":true,"why":"Elle objective l'obstruction réversible ; on y ajoute un test à la méthacholine si la spirométrie est normale."},{"t":"Un test à la méthacholine d'emblée chez tous les patients","ok":false,"why":"Il n'est proposé que lorsque la spirométrie est normale."},{"t":"Un bilan allergologique (interrogatoire et prick-tests)","ok":true,"why":"Il est réalisé lors du diagnostic."}],"explanation":"Bilan initial : examen avec auscultation, recherche des facteurs favorisants, bilan allergologique, radiographie thoracique et EFR (spirométrie avec test de réversibilité ± méthacholine).","src":"p. 89-90"},{"id":"p188-qcm-104","type":"QRM","rank":"B","objective":"p188-obj-04","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Un coiffeur de 35 ans développe un asthme depuis quelques mois. Quels arguments sont en faveur d'une origine professionnelle ?","options":[{"t":"Symptômes améliorés le week-end et disparus pendant les congés","ok":true,"why":"C'est le rythme professionnel : déclenchement au poste de travail, amélioration en dehors."},{"t":"Symptômes identiques au poste de travail, le week-end et en congés","ok":false,"why":"L'absence de rythme professionnel n'est pas en faveur d'une origine professionnelle."},{"t":"Variations du DEP en fonction du travail","ok":true,"why":"Une relation objective entre symptômes et travail se démontre par les variations du DEP ou du VEMS."},{"t":"Asthme présent depuis l'enfance, bien avant le début du métier","ok":false,"why":"L'argument est l'apparition de novo d'un asthme sur le lieu de travail."},{"t":"Sensibilisation IgE-dépendante prouvée par tests cutanés ou IgE spécifiques","ok":true,"why":"En cas de mécanisme IgE-dépendant, la sensibilisation immunologique est un argument."}],"explanation":"Arguments : début de novo sur le lieu de travail, métier à risque, rythme professionnel, relation objective symptômes-travail (DEP, VEMS), sensibilisation IgE-dépendante ; exceptionnellement, test de provocation spécifique en cabine.","src":"p. 90"},{"id":"p188-qcm-105","type":"QRM","rank":"A","objective":"p188-obj-08","tags":["étiologie"],"difficulty":2,"stem":"Parmi les associations métier – agent incriminé suivantes dans l'asthme professionnel, lesquelles sont exactes ?","options":[{"t":"Soignant – persulfates alcalins","ok":false,"why":"Chez les soignants : latex, aldéhydes, ammoniums quaternaires, oxyde d'éthylène. Les persulfates concernent les coiffeurs."},{"t":"Peintre au pistolet automobile – isocyanates","ok":true,"why":"Composants des peintures polyuréthanes ; les solvants ne font qu'aggraver cet asthme."},{"t":"Coiffeur – persulfates alcalins","ok":true,"why":"Produits de décoloration capillaire : agent majeur chez les coiffeurs."},{"t":"Travailleur du bois – farines de céréales","ok":false,"why":"Chez les travailleurs du bois : bois exotiques, colles (colophane, formaldéhyde) et vernis (isocyanates)."},{"t":"Boulanger-pâtissier – farines de céréales et alpha-amylase","ok":true,"why":"Farines (blé, seigle) et enzymes améliorants de la farine (alpha-amylase, cellulase) sont incriminés."}],"explanation":"Six métiers se partagent 50 % des asthmes professionnels : boulangers-pâtissiers, métiers de la santé, coiffeurs, peintres au pistolet automobile, travailleurs du bois et métiers du nettoyage.","src":"p. 90"},{"id":"p188-qcm-106","type":"QRM","rank":"A","objective":"p188-obj-21","tags":["suivi","traitement"],"difficulty":2,"stem":"Dans quelles situations faut-il adresser un patient asthmatique au pneumologue ?","options":[{"t":"Obstruction bronchique avec un VEMS inférieur à 80 %","ok":true,"why":"Cette obstruction justifie un avis pneumologique."},{"t":"Asthme bien contrôlé sous CSI faible dose, VEMS à 95 % de la valeur prédite","ok":false,"why":"Dans une grande proportion de cas, le médecin traitant prend en charge l'asthme."},{"t":"Traitement de fond par corticoïdes inhalés à dose moyenne ou forte","ok":true,"why":"Le recours au pneumologue est nécessaire dans cette situation."},{"t":"Toute première consultation pour asthme, quelle que soit la situation","ok":false,"why":"Le recours est réservé à des situations précises (diagnostic différentiel, VEMS < 80 %, CSI dose moyenne ou forte, contrôle non obtenu, asthme sévère…)."},{"t":"Asthme sévère (CSI forte dose + BDLA), pour ne pas retarder une biothérapie","ok":true,"why":"L'avis du pneumologue évite de retarder l'introduction d'une biothérapie si elle est nécessaire."}],"explanation":"Autres indications : diagnostic différentiel ou associé évoqué, spirométrie non disponible, plus de 500 mg de corticothérapie orale par an et/ou 3 flacons de BDCA par an, contrôle non obtenu malgré une prise en charge optimale.","src":"p. 95"},{"id":"p188-qcm-107","type":"QRM","rank":"A","objective":"p188-obj-05","tags":["suivi"],"difficulty":2,"stem":"Quels éléments sont en faveur d'un asthme contrôlé ?","options":[{"t":"Score ACT de 16/25","ok":false,"why":"Un score inférieur à 20/25 traduit un asthme insuffisamment contrôlé."},{"t":"Score ACT de 22/25","ok":true,"why":"L'asthme est bien contrôlé si le score ACT est d'au moins 20/25."},{"t":"Trois cures de corticoïdes systémiques l'année précédente","ok":false,"why":"Les exacerbations doivent être rares (moins de 2 cures) ; chaque cure impose de réévaluer le traitement de fond."},{"t":"Une seule cure de corticoïdes systémiques l'année précédente","ok":true,"why":"Exacerbations rares : moins de 2 cures de corticothérapie systémique l'année précédente."},{"t":"VEMS/CVF à 0,75 et VEMS à 90 % de la valeur prédite","ok":true,"why":"Absence d'obstruction bronchique : VEMS/CVF > 0,7 et VEMS ≥ 80 %."}],"explanation":"Contrôle = symptômes contrôlés (ACT sur les 4 dernières semaines), exacerbations rares ou absentes, absence d'obstruction bronchique.","src":"p. 93-94"},{"id":"p188-qcm-108","type":"QRM","rank":"A","objective":"p188-obj-22","tags":["urgence","traitement"],"difficulty":2,"stem":"Un asthmatique de 28 ans présente une exacerbation sans signe de gravité, prise en charge en ambulatoire. Quelles mesures sont recommandées ?","options":[{"t":"β2-mimétiques de courte durée d'action par voie inhalée, avec chambre d'inhalation si possible","ok":true,"why":"La voie inhalée est supérieure et plus sûre que les voies sous-cutanée et intraveineuse."},{"t":"β2-mimétiques en perfusion intraveineuse d'emblée","ok":false,"why":"La voie injectable n'est qu'une option en cas d'échec d'une exacerbation sévère, sous scope."},{"t":"Corticothérapie orale précoce pendant 5 à 7 jours, puis arrêt","ok":true,"why":"Prednisone ou prednisolone, 0,5 à 1 mg/kg/j sans dépasser 60 mg/j."},{"t":"Décroissance progressive de la corticothérapie sur plusieurs semaines","ok":false,"why":"Arrêt sans décroissance après 5 à 7 jours."},{"t":"Recherche et traitement d'un facteur favorisant (infection, médicament, allergène)","ok":true,"why":"Elle fait partie de la prise en charge, avec une réévaluation clinique très rapprochée."}],"explanation":"Exacerbation modérée : bronchodilatateurs inhalés, corticoïdes oraux sans retard, oxygène si hypoxémie, traitement du facteur favorisant, réévaluation à 1 h ; transfert en soins intensifs si aggravation ou non-amélioration.","src":"p. 97-98"},{"id":"p188-qcm-109","type":"QRM","rank":"A","objective":"p188-obj-22","tags":["urgence","traitement"],"difficulty":2,"stem":"Un asthmatique de 25 ans est pris en charge pour un asthme aigu grave. Quelles mesures sont recommandées ?","options":[{"t":"Corticothérapie systémique à éviter en cas de suspicion d'infection associée","ok":false,"why":"Elle ne doit pas être retardée et n'a aucune contre-indication, y compris en cas de suspicion de COVID-19."},{"t":"Transfert médicalisé en soins intensifs, organisé d'emblée","ok":true,"why":"Il ne doit pas retarder la mise en route immédiate du traitement."},{"t":"β2-mimétiques nébulisés à forte dose, associés à l'ipratropium","ok":true,"why":"5 mg toutes les 20 min la 1re heure ; ipratropium 0,5 mg répétable toutes les 8 h."},{"t":"Scope inutile en cas de β2-mimétique injectable","ok":false,"why":"Le scope est obligatoire : effet adrénergique et hypokaliémie majorée par la corticothérapie."},{"t":"Oxygène avec une cible de SpO2 de 93 à 95 %","ok":true,"why":"C'est l'objectif de l'exacerbation sévère."}],"explanation":"Asthme aigu grave : USI d'emblée, oxygène (SpO2 93-95 %), β2-mimétiques + ipratropium nébulisés (oxygène comme gaz vecteur), corticoïdes sans retard, ventilation mécanique si signe de gravité extrême.","src":"p. 98"},{"id":"p188-qcm-110","type":"QRM","rank":"A","objective":"p188-obj-02","tags":["diagnostic"],"difficulty":2,"stem":"Un homme de 22 ans consulte pour prurit nasal, éternuements en salves, rhinorrhée et obstruction nasale évoquant une rhinite allergique. Quelles propositions sont exactes ?","options":[{"t":"Le diagnostic est clinique","ok":true,"why":"Il repose sur les symptômes (PAREO), l'examen des fosses nasales et la recherche de sensibilisations allergéniques."},{"t":"Un bilan radiologique systématique est nécessaire","ok":false,"why":"Pas de bilan radiologique, sauf recherche d'un diagnostic différentiel ou associé."},{"t":"Le caractère allergique doit être argumenté","ok":true,"why":"Il existe un grand nombre de rhinites chroniques non allergiques."},{"t":"L'anosmie exclut le diagnostic de rhinite","ok":false,"why":"L'anosmie fait partie des symptômes de l'acronyme PAREO."},{"t":"L'examen des fosses nasales recherche une muqueuse inflammatoire et d'éventuels polypes","ok":true,"why":"Il se fait au spéculum nasal ou, à défaut, à l'otoscope."}],"explanation":"La rhinite allergique est une rhinite avec stigmates d'allergie respiratoire (inflammation IgE-dépendante) ; le patient est souvent polysensibilisé et l'interrogatoire établit les allergènes réellement responsables.","src":"p. 85, 101"},{"id":"p188-qcm-111","type":"QRM","rank":"A","objective":"p188-obj-18","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant les bêta-2 mimétiques de longue durée d'action (BDLA) dans l'asthme, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Ils peuvent être prescrits seuls dans un asthme léger","ok":false,"why":"Jamais de BDLA seul : l'asthme est une maladie inflammatoire."},{"t":"Le salmétérol est le seul BDLA à action rapide","ok":false,"why":"Le seul BDLA à action rapide est le formotérol."},{"t":"Ils doivent toujours être associés à un corticoïde inhalé","ok":true,"why":"Leur utilisation seule augmente le risque de décès par asthme."},{"t":"Ils constituent le traitement anti-inflammatoire le plus efficace de l'asthme","ok":false,"why":"Le traitement anti-inflammatoire le plus efficace est le corticoïde inhalé."},{"t":"Ils sont réservés au traitement des exacerbations sévères","ok":false,"why":"Ils font partie du traitement de fond, en association au CSI (paliers 3 à 5)."}],"explanation":"Les BDLA (salmétérol, formotérol) s'utilisent toujours avec un CSI, idéalement dans le même dispositif.","src":"p. 91-92, 100"},{"id":"p188-qcm-112","type":"QRM","rank":"A","objective":"p188-obj-03","tags":["imagerie","pièges"],"difficulty":2,"stem":"Concernant l'imagerie thoracique dans l'asthme, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La radiographie thoracique est recommandée à chaque consultation de suivi","ok":false,"why":"Elle n'est pas recommandée dans le suivi."},{"t":"La TDM thoracique est indispensable au diagnostic d'asthme","ok":false,"why":"Elle n'est pas nécessaire ; elle est réservée aux asthmes difficiles à contrôler."},{"t":"La radiographie thoracique est inutile lors d'une exacerbation grave","ok":false,"why":"Elle est indiquée pour vérifier l'absence de pneumothorax ou de pneumonie."},{"t":"La radiographie thoracique est indispensable lors de la première consultation","ok":true,"why":"Elle sert au diagnostic différentiel (obstacle bronchique ou trachéal)."},{"t":"Une TDM thoracique est réalisée de principe chez tout asthmatique pour chercher des bronchectasies","ok":false,"why":"Le diagnostic de bronchectasies est morphologique (TDM), mais la TDM n'est envisagée que dans les asthmes difficiles à contrôler."}],"explanation":"Radiographie thoracique : 1re consultation et exacerbations graves, pas dans le suivi. TDM : seulement asthme difficile à contrôler, pour rechercher une pathologie associée.","src":"p. 89"},{"id":"p188-qcm-113","type":"QRM","rank":"A","objective":"p188-obj-15","tags":["urgence","pièges"],"difficulty":1,"stem":"Parmi les éléments suivants, lequel (lesquels) constitue(nt) un facteur de risque de décès par asthme ?","options":[{"t":"Un suivi codifié régulier de l'asthme par le médecin traitant","ok":false,"why":"C'est l'absence de suivi codifié qui est un facteur de risque."},{"t":"Une prise quotidienne de corticoïdes inhalés, bien observée","ok":false,"why":"L'arrêt ou l'absence de CSI est un facteur de risque, pas leur prise régulière."},{"t":"Un antécédent d'exacerbation sévère avec intubation","ok":true,"why":"Un antécédent de passage en réanimation ou d'intubation avec ventilation mécanique figure parmi les facteurs de risque de décès."},{"t":"Une activité physique pratiquée régulièrement","ok":false,"why":"Elle est encouragée de façon systématique chez l'asthmatique."},{"t":"Une vaccination antigrippale à jour","ok":false,"why":"Elle est recommandée chez tous les asthmatiques."}],"explanation":"Facteurs de risque de décès : antécédent d'exacerbation sévère (réanimation, intubation), hospitalisation ou urgences dans l'année, corticothérapie orale actuelle ou récente, mauvaise observance, maladie psychiatrique, allergie alimentaire, hypersensibilité à l'aspirine/AINS, tabagisme actif et cannabis.","src":"p. 97"},{"id":"p188-qcm-114","type":"QRM","rank":"A","objective":"p188-obj-17","tags":["traitement","pièges"],"difficulty":1,"stem":"Concernant les vasoconstricteurs nasaux dans la rhinite allergique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Ils constituent le traitement de 1re intention","ok":false,"why":"Les traitements de 1re intention sont les antihistaminiques et les corticoïdes nasaux."},{"t":"Ils sont recommandés en cure continue dans les formes persistantes sévères","ok":false,"why":"Ils sont déconseillés au long cours."},{"t":"Ils sont sans risque chez le patient coronarien","ok":false,"why":"Il existe un risque de coronarospasme chez les coronariens."},{"t":"Ils modifient l'histoire naturelle de la rhinite allergique","ok":false,"why":"Seules les mesures d'éviction et l'immunothérapie allergénique le peuvent."},{"t":"Ils sont déconseillés au long cours (rhinite iatrogène)","ok":true,"why":"Risque de rhinite iatrogène, et de coronarospasme chez les patients coronariens."}],"explanation":"Traitement de la rhinite allergique : prise en charge du facteur allergique, lavage nasal au sérum physiologique, antihistaminiques et corticoïdes nasaux. Les vasoconstricteurs nasaux sont déconseillés au long cours.","src":"p. 101-102"},{"id":"p188-qcm-115","type":"QRM","rank":"A","objective":"p188-obj-22","tags":["urgence","traitement"],"difficulty":2,"stem":"Concernant la corticothérapie systémique dans une exacerbation sévère d'asthme, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elle est contre-indiquée en cas de suspicion de COVID-19","ok":false,"why":"Elle ne présente aucune contre-indication, y compris en cas de suspicion de COVID-19."},{"t":"Elle n'est débutée qu'après l'échec des bronchodilatateurs","ok":false,"why":"Elle doit être débutée sans retard."},{"t":"La voie intraveineuse est toujours préférée à la voie orale","ok":false,"why":"La voie orale est préférée en l'absence de trouble de la conscience."},{"t":"Elle doit être débutée sans retard, sans contre-indication","ok":true,"why":"Elle ne doit pas être retardée et n'a aucune contre-indication, même en cas de suspicion d'infection associée."},{"t":"Elle s'arrête progressivement sur 3 semaines","ok":false,"why":"La durée est de 5 à 7 jours puis arrêt sans décroissance."}],"explanation":"Prednisone ou prednisolone 0,5 à 1 mg/kg/j (maximum 60 mg/j), 5 à 7 jours, arrêt sans décroissance ; efficace en 4 à 6 h.","src":"p. 97-98, 100"},{"id":"p188-qcm-116","type":"QRM","rank":"A","objective":"p188-obj-21","tags":["suivi"],"difficulty":2,"stem":"Concernant le suivi d'un patient asthmatique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une radiographie thoracique est réalisée à chaque consultation","ok":false,"why":"Elle n'est pas recommandée dans le suivi."},{"t":"Le suivi pendant la grossesse est trimestriel","ok":false,"why":"Le suivi est mensuel pendant la grossesse."},{"t":"La technique d'inhalation est vérifiée une seule fois, lors de la prescription","ok":false,"why":"Elle est vérifiée à chaque consultation."},{"t":"En l'absence de symptôme, le suivi peut être espacé de 5 ans","ok":false,"why":"Le suivi périodique a lieu au minimum une fois par an."},{"t":"Une consultation est prévue 3 mois après tout changement de traitement","ok":true,"why":"Le suivi est adapté à la sévérité, au minimum annuel, avec consultation à 3 mois après chaque changement."}],"explanation":"Le suivi comporte l'ACT, ± la fonction respiratoire, la vérification de l'observance, de la technique d'inhalation, des effets secondaires et du plan d'action, et la prise en charge des facteurs favorisants.","src":"p. 94-95"},{"id":"p188-qcm-117","type":"QRM","rank":"B","objective":"p188-obj-06","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant la physiopathologie de l'asthme, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'asthme non-T2 dépend entièrement des lymphocytes Th2","ok":false,"why":"L'inflammation non-T2 ne dépend pas complètement des lymphocytes Th2 ni des éosinophiles."},{"t":"L'inflammation bronchique est le plus souvent à polynucléaires neutrophiles","ok":false,"why":"Elle est le plus souvent à éosinophiles."},{"t":"L'asthme T2 implique les lymphocytes Th2 et les éosinophiles","ok":true,"why":"Il s'observe dans les asthmes allergiques et dans les asthmes à éosinophiles non allergiques."},{"t":"Les voies aériennes ne subissent aucune modification de structure","ok":false,"why":"L'épithélium, le muscle lisse et la matrice extracellulaire sont modifiés."},{"t":"L'hyperréactivité bronchique n'intervient pas dans les symptômes","ok":false,"why":"Inflammation, modifications de structure des voies aériennes et hyperréactivité sont responsables des symptômes aigus et chroniques."}],"explanation":"Trois mécanismes : inflammation bronchique chronique (le plus souvent à éosinophiles), modifications structurales des voies aériennes et hyperréactivité bronchique. Deux phénotypes : asthme T2 et non-T2.","src":"p. 87"},{"id":"p188-qcm-118","type":"QRM","rank":"A","objective":"p188-obj-18","tags":["pièges","traitement"],"difficulty":2,"stem":"Chez un asthmatique non contrôlé, quelle prescription nécessite l'avis du pneumologue ?","options":[{"t":"Un vaccin antigrippal","ok":false,"why":"Il est recommandé chez tous les asthmatiques."},{"t":"Un antihistaminique pour une rhinite allergique associée","ok":false,"why":"La prise en charge de la rhinite fait partie du contrôle de l'asthme."},{"t":"Un collyre bêta-bloquant","ok":true,"why":"Les β-bloquants, y compris en collyre, peuvent aggraver l'asthme : leur prescription nécessite l'avis du pneumologue chez l'asthmatique non contrôlé."},{"t":"Un bronchodilatateur de courte durée d'action à la demande","ok":false,"why":"C'est le traitement de secours des symptômes."},{"t":"Un corticoïde inhalé à faible dose","ok":false,"why":"C'est la base du traitement de fond."}],"explanation":"Les β-bloquants (même en collyre) peuvent aggraver un asthme ; l'aspirine et les AINS sont contre-indiqués en cas d'antécédent d'hypersensibilité.","src":"p. 93"},{"id":"p188-qcm-119","type":"QRM","rank":"A","objective":"p188-obj-15","tags":["urgence","clinique"],"difficulty":2,"stem":"Un asthmatique de 30 ans arrive aux urgences : il ne prononce que quelques mots, est assis penché en avant, sa fréquence respiratoire est à 34/min et son DEP à 40 % de sa meilleure valeur. Quels éléments sont des critères de gravité de l'exacerbation ?","options":[{"t":"Fréquence respiratoire de 34/min","ok":true,"why":"Une FR supérieure à 30/min est un critère de gravité."},{"t":"Fréquence respiratoire de 18/min","ok":false,"why":"Le critère de gravité est une FR supérieure à 30/min."},{"t":"DEP à 40 % de la meilleure valeur","ok":true,"why":"Un DEP ≤ 50 % de la meilleure valeur (ou de la valeur théorique) est un critère de gravité."},{"t":"SpO2 à 98 % en air ambiant","ok":false,"why":"Le critère de gravité est une SpO2 inférieure à 90 % en air."},{"t":"Parole par mots isolés","ok":true,"why":"Parler avec des mots (et non des phrases) est un signe de gravité."}],"explanation":"Parmi les critères de gravité : parole par mots, position penchée en avant, agitation, FR > 30/min, muscles respiratoires accessoires, FC > 120/min, SpO2 < 90 % en air, DEP ≤ 50 %. Les signes de défaillance sont encore plus alarmants.","src":"p. 96"},{"id":"p188-qcm-120","type":"QRM","rank":"A","objective":"p188-obj-24","tags":["prévention","traitement"],"difficulty":2,"stem":"Quelles mesures font partie de la prise en charge des facteurs favorisants de l'asthme ?","options":[{"t":"Éviction de toute activité physique","ok":false,"why":"Une activité physique régulière est encouragée de façon systématique."},{"t":"Encouragement fort et répété au sevrage tabagique","ok":true,"why":"Il fait partie de la prise en charge des facteurs associés."},{"t":"Vaccination antipneumococcique chez tous les asthmatiques","ok":false,"why":"Elle est recommandée en cas d'asthme sévère ; la vaccination antigrippale est recommandée chez tous."},{"t":"Éviction des irritants domestiques et professionnels (produits ménagers, parfums d'intérieur, moisissures)","ok":true,"why":"L'asthme ne peut pas être contrôlé si ces facteurs favorisants ne sont pas pris en charge."},{"t":"Vaccination antigrippale chez tous les asthmatiques","ok":true,"why":"La vaccination anti-COVID doit aussi être à jour."}],"explanation":"Prise en charge des facteurs associés : rhinite, allergies, sevrage tabagique, éviction des irritants, médicaments aggravants (β-bloquants, aspirine/AINS si hypersensibilité), comorbidités, prévention des infections respiratoires et activité physique régulière.","src":"p. 93"},{"id":"p188-qru-101","type":"QRU","rank":"A","objective":"p188-obj-18","tags":["traitement"],"difficulty":1,"stem":"Une femme de 32 ans, asthmatique, utilise son bronchodilatateur de courte durée d'action plus de 2 fois par mois. Quel traitement de fond instaurer ?","options":[{"t":"Un β2-mimétique de longue durée d'action seul","ok":false,"why":"Jamais de BDLA seul : l'asthme est une maladie inflammatoire et le BDLA seul augmente le risque de décès."},{"t":"Un bronchodilatateur de courte durée d'action seul, à la demande","ok":false,"why":"C'est le traitement de secours : des symptômes plus de 2 fois par mois imposent un traitement de fond."},{"t":"Une corticothérapie orale au long cours","ok":false,"why":"Elle n'est utilisée que dans certains asthmes sévères, en coordination avec le pneumologue, si une biothérapie n'est pas disponible."},{"t":"Un corticoïde inhalé, à prendre tous les jours","ok":true,"why":"Le traitement de fond repose sur la corticothérapie inhalée, débutée au palier 2 ou 3."},{"t":"Un antihistaminique H1 de 2e génération","ok":false,"why":"C'est un traitement de la rhinite allergique, pas le traitement de fond de l'asthme."}],"explanation":"Des symptômes survenant plus de 2 fois par mois nécessitent un traitement de fond quotidien : corticoïdes inhalés, seuls ou associés à un bronchodilatateur.","src":"p. 91, 100"},{"id":"p188-qru-102","type":"QRU","rank":"A","objective":"p188-obj-21","tags":["suivi","traitement"],"difficulty":3,"stem":"Un patient asthmatique traité par CSI à faible dose a un score ACT à 16/25 et a reçu 3 cures de corticoïdes oraux dans l'année. Avant de passer au palier supérieur, que faut-il faire en priorité ?","options":[{"t":"Passer d'emblée au palier supérieur sans autre évaluation préalable","ok":false,"why":"On vérifie d'abord l'absence de cause de non-contrôle."},{"t":"Arrêter le CSI et le remplacer par un BDLA seul pour simplifier le traitement","ok":false,"why":"Jamais de BDLA seul."},{"t":"Prescrire une radiographie thoracique à chaque consultation de suivi","ok":false,"why":"La radiographie thoracique n'est pas recommandée dans le suivi."},{"t":"Maintenir le même traitement pendant 6 mois sans réévaluation","ok":false,"why":"Le contrôle est évalué à chaque consultation, 1 à 3 mois après toute modification du traitement de fond."},{"t":"Vérifier l'observance, la technique d'inhalation et les facteurs favorisants","ok":true,"why":"Ce sont les causes de non-contrôle à rechercher avant d'augmenter le traitement."}],"explanation":"Asthme non contrôlé : on vérifie observance, technique de prise des inhalateurs et facteurs favorisants avant de monter d'un palier ; si le non-contrôle persiste, recours au spécialiste ou à un centre expert.","src":"p. 94"},{"id":"p188-qru-103","type":"QRU","rank":"A","objective":"p188-obj-22","tags":["urgence","paraclinique"],"difficulty":2,"stem":"Lors de la prise en charge d'une exacerbation d'asthme, quelle attitude est recommandée pour les examens complémentaires ?","options":[{"t":"Attendre la radiographie thoracique avant le premier bronchodilatateur","ok":false,"why":"Le traitement est une urgence thérapeutique et ne doit pas être retardé."},{"t":"Réaliser systématiquement une gazométrie artérielle, même sans signe de gravité","ok":false,"why":"Elle est demandée en présence de critères de sévérité, à la recherche d'une hypercapnie."},{"t":"Les réaliser en parallèle du traitement, sans le retarder","ok":true,"why":"Les examens complémentaires ne doivent pas retarder la prise en charge."},{"t":"Réaliser systématiquement une TDM thoracique","ok":false,"why":"La radiographie thoracique suffit pour chercher un diagnostic différentiel ou une complication."},{"t":"Ne demander aucun examen, même en cas de signe de gravité","ok":false,"why":"Radiographie thoracique et gazométrie (si critères de sévérité) font partie du bilan."}],"explanation":"Bilan de l'exacerbation : radiographie thoracique (diagnostic différentiel, complications) et gazométrie artérielle si critères de sévérité, toujours en parallèle du traitement.","src":"p. 97"},{"id":"p188-qru-104","type":"QRU","rank":"A","objective":"p188-obj-22","tags":["urgence","biologie"],"difficulty":1,"stem":"Quel trouble biologique est favorisé à la fois par les β2-mimétiques à forte dose et par la corticothérapie systémique dans l'asthme aigu grave ?","options":[{"t":"Hyperkaliémie","ok":false,"why":"Le chapitre signale le risque inverse : l'hypokaliémie."},{"t":"Hypoglycémie","ok":false,"why":"Les corticoïdes exposent à l'hyperglycémie."},{"t":"Hypokaliémie","ok":true,"why":"Elle est favorisée par les BDCA et majorée par les corticoïdes : d'où le scope lors des β2-mimétiques injectables."},{"t":"Hypernatrémie","ok":false,"why":"Elle n'est pas citée parmi les complications à surveiller."},{"t":"Hypercalcémie","ok":false,"why":"Elle n'est pas citée parmi les complications à surveiller."}],"explanation":"Complications à surveiller : hyperglycémie (corticoïdes), hypokaliémie (BDCA et corticoïdes), acidose lactique (BDCA), tachycardie et troubles du rythme (BDCA et hypokaliémie).","src":"p. 98"},{"id":"p188-qru-105","type":"QRU","rank":"A","objective":"p188-obj-02","tags":["diagnostic"],"difficulty":3,"stem":"Un patient de 19 ans présente chaque année prurit nasal, éternuements et obstruction nasale pendant 6 semaines consécutives, avec un sommeil perturbé. Comment classer sa rhinite allergique ?","options":[{"t":"Intermittente et légère","ok":false,"why":"Intermittente = au plus 4 semaines consécutives par an ; légère = sommeil et activités normaux."},{"t":"Intermittente et sévère","ok":false,"why":"Plus de 4 semaines consécutives par an : la rhinite est persistante."},{"t":"Persistante et légère","ok":false,"why":"Un sommeil perturbé suffit à la classer comme sévère."},{"t":"Non classable sans bilan radiologique","ok":false,"why":"La classification repose sur la durée et la sévérité des symptômes ; il n'y a pas de bilan radiologique de principe."},{"t":"Persistante et sévère","ok":true,"why":"Plus de 4 semaines consécutives par an = persistante ; au moins 1 item de retentissement (sommeil perturbé) = sévère."}],"explanation":"Classification de la rhinite allergique : durée (intermittente ≤ 4 semaines/an, persistante > 4 semaines/an) et sévérité (légère, ou sévère dès qu'un item est perturbé : sommeil, activités sociales/sportives, scolaires/professionnelles, symptômes gênants).","src":"p. 101"},{"id":"p188-qru-106","type":"QRU","rank":"A","objective":"p188-obj-14","tags":["définition","clinique"],"difficulty":2,"stem":"Laquelle de ces situations correspond à une exacerbation d'asthme ?","options":[{"t":"Gêne respiratoire de quelques minutes, cédant en moins de 20 minutes sous bronchodilatateur","ok":false,"why":"C'est un épisode de symptômes d'asthme de brève durée, à ne pas confondre avec une exacerbation."},{"t":"Toux nocturne isolée, cédant spontanément","ok":false,"why":"Symptôme bref, réversible spontanément : ce n'est pas une exacerbation."},{"t":"Sibilants entendus dans le passé, sans symptôme actuel","ok":false,"why":"Une exacerbation est une aggravation actuelle des symptômes."},{"t":"Aggravation progressive depuis 3 jours, non calmée par les bronchodilatateurs répétés","ok":true,"why":"Aggravation d'au moins 2 jours nécessitant une modification du traitement, non calmée par les BDCA et sans retour à l'état habituel."},{"t":"VEMS/CVF à 0,65 sans aucun symptôme","ok":false,"why":"Une exacerbation est définie par l'aggravation des symptômes, pas par une mesure isolée."}],"explanation":"Exacerbation : aggravation progressive des symptômes durant au moins 2 jours, avec modification du traitement et souvent recours inopiné aux soins, non calmée par les BDCA répétés, sans retour à l'état habituel.","src":"p. 86"},{"id":"p188-qru-107","type":"QRU","rank":"B","objective":"p188-obj-16","tags":["épidémiologie"],"difficulty":2,"stem":"Quelle proportion approximative des patients asthmatiques présente une rhinite allergique ?","options":[{"t":"80 %","ok":true,"why":"La rhinite allergique touche environ 80 % des asthmatiques."},{"t":"25 %","ok":false,"why":"C'est la prévalence de la rhinite allergique dans la population générale."},{"t":"10 %","ok":false,"why":"Beaucoup trop bas : la rhinite est très fréquente chez l'asthmatique."},{"t":"50 %","ok":false,"why":"Le chapitre donne 80 %."},{"t":"100 %","ok":false,"why":"L'association est très fréquente mais non systématique."}],"explanation":"Prévalence de l'asthme de l'adulte en France : 6 % ; rhinite allergique : 24 % ; rhinite allergique chez 80 % des asthmatiques et 25 % de la population générale.","src":"p. 86"},{"id":"p188-qru-108","type":"QRU","rank":"A","objective":"p188-obj-25","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement médicamenteux de première intention de la rhinite allergique, quelle affirmation est exacte ?","options":[{"t":"Les corticoïdes nasaux sont systématiquement préférés aux antihistaminiques","ok":false,"why":"Les recommandations ne font pas de préférence entre les deux en 1re intention."},{"t":"Les antihistaminiques ne s'utilisent jamais par voie locale","ok":false,"why":"Les antihistaminiques s'utilisent par voie orale et/ou locale."},{"t":"Il n'y a pas de préférence entre antihistaminiques et corticoïdes nasaux","ok":true,"why":"Ils peuvent être associés en cas d'inefficacité."},{"t":"Les vasoconstricteurs nasaux sont recommandés en cure continue","ok":false,"why":"Ils sont déconseillés au long cours (rhinite iatrogène, coronarospasme chez les coronariens)."},{"t":"L'association de deux traitements est interdite","ok":false,"why":"Les traitements peuvent être associés en cas d'inefficacité."}],"explanation":"Rhinite allergique : lavage nasal au sérum physiologique, antihistaminiques (voie orale et/ou locale) et corticoïdes nasaux sans préférence en 1re intention ; éviction allergénique et immunothérapie pour modifier l'histoire naturelle.","src":"p. 85, 101-102"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p188-pareto","points":[{"id":"p188-par-01","rank":"A","cat":"définition","text":"Asthme = maladie inflammatoire chronique : **symptômes respiratoires variables** (dyspnée, sifflements, toux, oppression) + **obstruction bronchique variable/réversible**","src":"p. 86"},{"id":"p188-par-02","rank":"A","cat":"examen","text":"TVO = VEMS/CVF **< 0,7** ; réversible si VEMS **> 200 mL ET > 12 %** après BDCA. Spirométrie normale n'élimine pas l'asthme → test de réversibilité ou **méthacholine**","src":"p. 87-89"},{"id":"p188-par-03","rank":"A","cat":"traitement","text":"Traitement de fond = **CSI tous les jours** (dès symptômes **> 2 fois/mois**) ; **jamais de BDLA seul** (↑ risque de décès) ; début au palier 2 ou 3","src":"p. 91, 100"},{"id":"p188-par-04","rank":"A","cat":"traitement","text":"Paliers : **P3 = CSI faible dose + BDLA** ; P4 = CSI dose modérée + BDLA ; **P5 = CSI forte dose + BDLA** → pneumologue, tiotropium, biothérapie = **asthme sévère**","src":"p. 91-92"},{"id":"p188-par-05","rank":"A","cat":"traitement","text":"Secours = **BDCA** (salbutamol, terbutaline) ou CSI/**formotérol** (seul BDLA rapide) ; **plan d'action écrit** + technique d'inhalation vérifiée à chaque consultation","src":"p. 92-93"},{"id":"p188-par-06","rank":"A","cat":"suivi","text":"Asthme contrôlé : **ACT ≥ 20/25**, **< 2 cures** de corticoïdes systémiques/an, **VEMS/CVF > 0,7 et VEMS ≥ 80 %** ; évaluer 1 à 3 mois après toute modification","src":"p. 93-94"},{"id":"p188-par-07","rank":"A","cat":"suivi","text":"Non contrôlé → vérifier **observance, technique d'inhalation, facteurs favorisants** AVANT de monter d'un palier ; si contrôlé : **CSI faible dose** minimum conservé","src":"p. 94"},{"id":"p188-par-08","rank":"A","cat":"gravité","text":"Exacerbation = aggravation **≥ 2 jours**, non calmée par BDCA. Gravité : parole par mots, FR > 30/min, **DEP ≤ 50 %**, SpO2 < 90 % ; défaillance : **silence auscultatoire**","src":"p. 86, 96"},{"id":"p188-par-09","rank":"A","cat":"gravité","text":"FDR de décès : ATCD de **réa/intubation**, urgences ou hospitalisation dans l'année, corticoïdes oraux, mauvaise observance, cannabis, **syndrome de Widal**","src":"p. 97"},{"id":"p188-par-10","rank":"A","cat":"traitement","text":"Exacerbation : **BDCA inhalés** (nébulisation 5 mg/20 min, O2) + **prednisone 0,5-1 mg/kg/j (max 60 mg) 5-7 j** sans décroissance ; réévaluer à **1 h**","src":"p. 97-99"},{"id":"p188-par-11","rank":"A","cat":"traitement","text":"Asthme aigu grave : USI d'emblée, SpO2 **93-95 %**, β2 nébulisés + **ipratropium**, corticoïdes **sans contre-indication**, scope si β2 IV, ventilation si gravité extrême","src":"p. 98"},{"id":"p188-par-12","rank":"A","cat":"examen","text":"Urgence, sans retarder le traitement : RP (pneumothorax, **pneumomédiastin**, emphysème sous-cutané) ; **gazométrie** si critères de sévérité (**hypercapnie**)","src":"p. 97"},{"id":"p188-par-13","rank":"A","cat":"piège","text":"À éviter : **β-bloquants** (même collyre), **aspirine/AINS** si hypersensibilité. À vacciner : **grippe** (tous), pneumocoque (asthme sévère), COVID à jour","src":"p. 93"},{"id":"p188-par-14","rank":"A","cat":"étiologie","text":"Asthme pro : coiffeurs → **persulfates** ; peintres → **isocyanates** ; boulangers → **farines** ; soignants → latex, aldéhydes. Preuve : DEP sur/hors travail","src":"p. 90"},{"id":"p188-par-15","rank":"A","cat":"clinique","text":"Rhinite allergique = **PAREO**, inflammation IgE-dépendante ; traitement = **antihistaminiques H1 + corticoïdes nasaux** ; **pas de vasoconstricteurs** au long cours","src":"p. 85, 101-102"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
